// O(1) Fast lookup maps
const REGION_MAP = new Map<string, Region>();
for (const r of REGIONS) {
  REGION_MAP.set(r.slug, r);
}

export function getRegionBySlug(slug: string): Region | undefined {
  return REGION_MAP.get(slug);
}

const DONGS_BY_PARENT = new Map<string, Region[]>();
for (const r of REGIONS) {
  if (r.parentSlug) {
    let list = DONGS_BY_PARENT.get(r.parentSlug);
    if (!list) {
      list = [];
      DONGS_BY_PARENT.set(r.parentSlug, list);
    }
    list.push(r);
  }
}

export function getDongsForCity(parentSlug: string): Region[] {
  return DONGS_BY_PARENT.get(parentSlug) || [];
}

export function getMainRegionsByProvince(): Record<string, Region[]> {
  const map: Record<string, Region[]> = {};
  for (const r of REGIONS) {
    if (r.isDong) continue;
    if (!map[r.province]) map[r.province] = [];
    map[r.province].push(r);
  }
  return map;
}

export function getRegionsByProvince(): Record<string, Region[]> {
  const map: Record<string, Region[]> = {};
  for (const r of REGIONS) {
    if (r.isDong) continue;
    if (!map[r.province]) map[r.province] = [];
    map[r.province].push(r);
  }
  return map;
}

export function getTable60Regions(): Region[] {
  return TABLE_60_CITIES.map((slug) => getRegionBySlug(slug)).filter((r): r is Region => Boolean(r));
}

export function getMainRegions(): Region[] {
  return REGIONS.filter((r) => !r.parentSlug && !r.isDong);
}
